import fs from 'node:fs/promises';
const d='data/research/short-squeeze-volume-20261107',read=async p=>JSON.parse(await fs.readFile(p)),x=await read(d+'/results.json'),examples=await read(d+'/recent-examples.json'),m=x.manifest,fmt=(v,n=2)=>Number.isFinite(v)?v.toFixed(n):'—',pct=v=>fmt(v)+'%',vn=t=>new Date(t).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour12:false});
